// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Load fonts at module level to prevent flickering and ensure availability at frame 0
const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();



export type PremiumBarChartProps = Record<string, any>;

const PremiumBarChart: React.FC<PremiumBarChartProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  chartTitle = "GLOBAL EV DELIVERIES",
  titleFontFamily = "Playfair Display",
  titleColor = "#111111",
  bydCarImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/889826377a8b44a5972bd18986589ef2.png",
  teslaCarImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/46ca6055e42248c9a5e632398c2e5c83.png",
  bydLogoImage = "data:image/svg+xml;base64,",
  teslaLogoImage = "data:image/svg+xml;base64,",
  bydValue = 3.2,
  teslaValue = 1.6,
  maxValueYAxis = 3.5,
  fontFamily = "Inter",
  barColorFront = "#111111",
  barColorSide = "#2a2a2a",
  barColorTop = "#1a1a1a",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const introDelay = 15;
  const barAnimation = spring({
    frame: frame - introDelay,
    fps,
    config: { damping: 14, mass: 1, stiffness: 60 },
  });

  const cameraScale = interpolate(frame, [0, fps * durationInSeconds], [1, 1.05]);
  const titleOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // Layout Calculations (Responsive based on Canvas)
  const marginLeft = width * 0.18;
  const marginRight = width * 0.12;
  const chartBottom = height * 0.82;
  const maxBarHeightPx = height * 0.55;

  const barWidth = width * 0.16;
  const depthX = width * 0.035;
  const depthY = -height * 0.015;

  const availableChartWidth = width - marginLeft - marginRight;
  const spacing = (availableChartWidth - barWidth * 2) / 3;

  const bydX = marginLeft + spacing;
  const teslaX = bydX + barWidth + spacing;

  // Grid Data
  const gridSteps = 7; // 0, 0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5 (8 lines)
  const gridValues = Array.from({ length: gridSteps + 1 }).map(
    (_, i) => (maxValueYAxis / gridSteps) * i
  );

  // Computed Heights per frame
  const bydCurrentValue = bydValue * barAnimation;
  const teslaCurrentValue = teslaValue * barAnimation;

  const bydHeightPx = (bydCurrentValue / maxValueYAxis) * maxBarHeightPx;
  const teslaHeightPx = (teslaCurrentValue / maxValueYAxis) * maxBarHeightPx;

  // Formatting helpers
  const formatValue = (val: number) => {
    if (val === 0) return "0";
    if (val < 1) return `${Math.round(val * 1000)}K`;
    return `${val.toFixed(1)}M`;
  };

  // Render a 3D Bar using SVG polygons
  const render3DBar = (
    x: number,
    baseY: number,
    h: number,
    colorFront: string,
    colorSide: string,
    colorTop: string
  ) => {
    // Front Face
    const pFront = `
      ${x},${baseY} 
      ${x + barWidth},${baseY} 
      ${x + barWidth},${baseY - h} 
      ${x},${baseY - h}
    `;

    // Right Side Face
    const pSide = `
      ${x + barWidth},${baseY} 
      ${x + barWidth + depthX},${baseY + depthY} 
      ${x + barWidth + depthX},${baseY - h + depthY} 
      ${x + barWidth},${baseY - h}
    `;

    // Top Face
    const pTop = `
      ${x},${baseY - h} 
      ${x + barWidth},${baseY - h} 
      ${x + barWidth + depthX},${baseY - h + depthY} 
      ${x + depthX},${baseY - h + depthY}
    `;

    return (
      <g>
        {/* Soft shadow under base */}
        <ellipse
          cx={x + barWidth / 2 + depthX / 2}
          cy={baseY + depthY / 2 + 10}
          rx={barWidth * 0.6}
          ry={height * 0.015}
          fill="rgba(0,0,0,0.15)"
          filter="blur(10px)"
        />
        <polygon points={pFront} fill={colorFront} />
        <polygon points={pSide} fill={colorSide} />
        <polygon points={pTop} fill={colorTop} />
        
        {/* Subtle highlight edges */}
        <polyline
          points={`${x},${baseY - h} ${x + barWidth},${baseY - h} ${x + barWidth + depthX},${baseY - h + depthY}`}
          fill="none"
          stroke="rgba(255,255,255,0.15)"
          strokeWidth="1.5"
        />
      </g>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: fontFamily === "Inter" ? interFamily : "sans-serif",
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          transform: `scale(${cameraScale})`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        {/* --- SVG Layer for Grid & 3D Shapes --- */}
        <svg
          width="100%"
          height="100%"
          style={{ position: "absolute", top: 0, left: 0 }}
        >
          <defs>
            <linearGradient id="gridLineGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="rgba(0,0,0,0.1)" />
              <stop offset="100%" stopColor="rgba(0,0,0,0)" />
            </linearGradient>
          </defs>

          {/* Y Axis Vertical Line */}
          <line
            x1={marginLeft - 20}
            y1={chartBottom - maxBarHeightPx - 50}
            x2={marginLeft - 20}
            y2={chartBottom}
            stroke="#000"
            strokeWidth="2"
          />

          {/* Grid Lines */}
          {gridValues.map((val) => {
            const yPos = chartBottom - (val / maxValueYAxis) * maxBarHeightPx;
            return (
              <g key={`grid-${val}`}>
                <line
                  x1={marginLeft - 25}
                  y1={yPos}
                  x2={marginLeft - 15}
                  y2={yPos}
                  stroke="#000"
                  strokeWidth="2"
                />
                <line
                  x1={marginLeft - 15}
                  y1={yPos}
                  x2={width * 0.9}
                  y2={yPos}
                  stroke="url(#gridLineGrad)"
                  strokeWidth="1.5"
                  strokeDasharray="8 6"
                />
              </g>
            );
          })}

          {/* X Axis Base Line */}
          <line
            x1={marginLeft - 20}
            y1={chartBottom}
            x2={width * 0.9}
            y2={chartBottom}
            stroke="#000"
            strokeWidth="2"
          />

          {/* Bars */}
          {render3DBar(
            bydX,
            chartBottom,
            bydHeightPx,
            barColorFront,
            barColorSide,
            barColorTop
          )}
          {render3DBar(
            teslaX,
            chartBottom,
            teslaHeightPx,
            barColorFront,
            barColorSide,
            barColorTop
          )}

          {/* Value Label Connectors (Pins) */}
          <line
            x1={bydX + barWidth / 2 + depthX / 2}
            y1={chartBottom - bydHeightPx + depthY / 2 - 140}
            x2={bydX + barWidth / 2 + depthX / 2}
            y2={chartBottom - bydHeightPx + depthY / 2 - 80}
            stroke="#000"
            strokeWidth="2"
          />
          <circle
            cx={bydX + barWidth / 2 + depthX / 2}
            cy={chartBottom - bydHeightPx + depthY / 2 - 80}
            r="4"
            fill="#000"
          />

          <line
            x1={teslaX + barWidth / 2 + depthX / 2}
            y1={chartBottom - teslaHeightPx + depthY / 2 - 140}
            x2={teslaX + barWidth / 2 + depthX / 2}
            y2={chartBottom - teslaHeightPx + depthY / 2 - 80}
            stroke="#000"
            strokeWidth="2"
          />
          <circle
            cx={teslaX + barWidth / 2 + depthX / 2}
            cy={chartBottom - teslaHeightPx + depthY / 2 - 80}
            r="4"
            fill="#000"
          />
        </svg>

        {/* --- HTML Layer for Text and Images --- */}
        <AbsoluteFill style={{ transition: "none" }}>
          
          {/* Newspaper Style Title */}
          <div
            style={{
              position: "absolute",
              top: height * 0.08,
              left: width * 0.1,
              width: width * 0.8,
              opacity: titleOpacity,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transition: "none",
            }}
          >
            <div
              style={{
                width: "100%",
                borderTop: `6px solid ${titleColor}`,
                borderBottom: `2px solid ${titleColor}`,
                padding: "20px 0",
                textAlign: "center",
                fontSize: width * 0.065,
                fontFamily: titleFontFamily === "Playfair Display" ? playfairFamily : interFamily,
                fontWeight: 900,
                color: titleColor,
                textTransform: "uppercase",
                lineHeight: 1.1,
                letterSpacing: "0.02em",
                transition: "none",
              }}
            >
              {chartTitle}
            </div>
          </div>

          {/* Y Axis Labels */}
          {gridValues.map((val) => {
            const yPos = chartBottom - (val / maxValueYAxis) * maxBarHeightPx;
            return (
              <div
                key={`label-${val}`}
                style={{
                  position: "absolute",
                  left: 0,
                  top: yPos,
                  width: marginLeft - 40,
                  textAlign: "right",
                  transform: "translateY(-50%)",
                  fontSize: width * 0.022,
                  fontWeight: 500,
                  color: "#111",
                  letterSpacing: "-0.02em",
                  transition: "none",
                }}
              >
                {formatValue(val)}
              </div>
            );
          })}

          {/* BYD Graphic Container */}
          <div
            style={{
              position: "absolute",
              left: bydX + barWidth / 2 + depthX / 2,
              bottom: height - chartBottom + bydHeightPx - depthY / 2,
              transform: "translateX(-50%)",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transition: "none",
            }}
          >
            {/* Hovering Value Label */}
            <div
              style={{
                position: "absolute",
                bottom: 160,
                fontSize: width * 0.035,
                fontWeight: 700,
                color: "#111",
                letterSpacing: "-0.03em",
                whiteSpace: "nowrap",
                opacity: barAnimation > 0.1 ? 1 : 0,
              }}
            >
              {formatValue(bydCurrentValue)}
            </div>

            {/* Car Image */}
            <Img
              src={bydCarImage}
              style={{
                width: width * 0.18,
                objectFit: "contain",
                marginBottom: -10, // Slight visual grounding on the top face
                filter: "drop-shadow(0px 10px 10px rgba(0,0,0,0.4))",
                transition: "none",
              }}
            />
          </div>

          {/* BYD Logo Image on Bar Front */}
          <div
            style={{
              position: "absolute",
              left: bydX,
              top: chartBottom - bydHeightPx + 40,
              width: barWidth,
              display: "flex",
              justifyContent: "center",
              opacity: barAnimation > 0.3 ? 1 : 0,
              transition: "none",
            }}
          >
            <Img
              src={bydLogoImage}
              style={{
                width: "60%",
                objectFit: "contain",
                transition: "none",
              }}
            />
          </div>

          {/* Tesla Graphic Container */}
          <div
            style={{
              position: "absolute",
              left: teslaX + barWidth / 2 + depthX / 2,
              bottom: height - chartBottom + teslaHeightPx - depthY / 2,
              transform: "translateX(-50%)",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transition: "none",
            }}
          >
            {/* Hovering Value Label */}
            <div
              style={{
                position: "absolute",
                bottom: 160,
                fontSize: width * 0.035,
                fontWeight: 700,
                color: "#111",
                letterSpacing: "-0.03em",
                whiteSpace: "nowrap",
                opacity: barAnimation > 0.1 ? 1 : 0,
              }}
            >
              {formatValue(teslaCurrentValue)}
            </div>

            {/* Car Image */}
            <Img
              src={teslaCarImage}
              style={{
                width: width * 0.18,
                objectFit: "contain",
                marginBottom: -10,
                filter: "drop-shadow(0px 10px 10px rgba(0,0,0,0.4))",
                transition: "none",
              }}
            />
          </div>

          {/* Tesla Logo Image on Bar Front */}
          <div
            style={{
              position: "absolute",
              left: teslaX,
              top: chartBottom - teslaHeightPx + 40,
              width: barWidth,
              display: "flex",
              justifyContent: "center",
              opacity: barAnimation > 0.3 ? 1 : 0,
              transition: "none",
            }}
          >
            <Img
              src={teslaLogoImage}
              style={{
                width: "60%",
                objectFit: "contain",
                transition: "none",
              }}
            />
          </div>

          {/* X Axis Labels */}
          <div
            style={{
              position: "absolute",
              left: bydX,
              top: chartBottom + 30,
              width: barWidth + depthX,
              textAlign: "center",
              fontSize: width * 0.022,
              fontWeight: 600,
              color: "#333",
              letterSpacing: "0.05em",
              transition: "none",
            }}
          >
            BYD
          </div>
          <div
            style={{
              position: "absolute",
              left: teslaX,
              top: chartBottom + 30,
              width: barWidth + depthX,
              textAlign: "center",
              fontSize: width * 0.022,
              fontWeight: 600,
              color: "#333",
              letterSpacing: "0.05em",
              transition: "none",
            }}
          >
            TESLA
          </div>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PremiumBarChart;